            title = "অধ্যায় ১ : ভাষা কী?",
            definition = "ভাষা হলো মানুষের ভাব, অনুভূতি, চিন্তা, জ্ঞান, অভিজ্ঞতা ও ইচ্ছা প্রকাশের প্রধান মাধ্যম। মানুষ মুখের ধ্বনি, লিখিত চিহ্ন, অঙ্গভঙ্গি বা প্রতীকের মাধ্যমে একে অপরের সঙ্গে যোগাযোগ স্থাপন করে। এই যোগাযোগের সবচেয়ে উন্নত ও কার্যকর মাধ্যমই হলো ভাষা।",
            explanation = """
১. ভাষার সংজ্ঞা
ভাষা হলো মানুষের ভাব, অনুভূতি, চিন্তা, জ্ঞান, অভিজ্ঞতা ও ইচ্ছা প্রকাশের প্রধান মাধ্যম। মানুষ মুখের ধ্বনি, লিখিত চিহ্ন, অঙ্গভঙ্গি বা প্রতীকের মাধ্যমে একে অপরের সঙ্গে যোগাযোগ স্থাপন করে। এই যোগাযোগের সবচেয়ে উন্নত ও কার্যকর মাধ্যমই হলো ভাষা।

সহজভাবে বলা যায়—
"মানুষ যে অর্থপূর্ণ ধ্বনি বা শব্দের মাধ্যমে নিজের মনের ভাব প্রকাশ করে এবং অন্যের ভাব বুঝতে পারে, তাকে ভাষা বলে।"

ভাষার প্রামাণ্য সংজ্ঞা:
ড. মুহম্মদ শহীদুল্লাহ বলেছেন,
"মানুষের কণ্ঠনিঃসৃত অর্থবোধক ধ্বনিসমষ্টিই ভাষা।"

ভাষাবিজ্ঞানের মতে,
"ভাষা হলো একটি সামাজিকভাবে স্বীকৃত ধ্বনি-প্রতীক ব্যবস্থা, যার মাধ্যমে মানুষ ভাবের আদান-প্রদান করে।"

২. ভাষার বৈশিষ্ট্য
ভাষার কয়েকটি গুরুত্বপূর্ণ বৈশিষ্ট্য নিচে তুলে ধরা হলো—
ক) ভাষা ভাব প্রকাশের মাধ্যম: মানুষ ভাষার মাধ্যমে আনন্দ, দুঃখ, রাগ, ভালোবাসা, আশা, হতাশা ইত্যাদি প্রকাশ করে। (উদাহরণ: "আমি আজ খুব আনন্দিত।")
খ) ভাষা অর্থবোধক: ভাষার প্রতিটি শব্দের নির্দিষ্ট অর্থ থাকে। (উদাহরণ: বই, নদী, বিদ্যালয়)
গ) ভাষা সামাজিক: ভাষা একা সৃষ্টি হয় না। সমাজে বসবাসকারী মানুষের মধ্যে যোগাযোগের প্রয়োজন থেকেই ভাষার সৃষ্টি হয়েছে।
ঘ) ভাষা পরিবর্তনশীল: সময়ের সঙ্গে ভাষার শব্দ, উচ্চারণ ও ব্যবহার পরিবর্তিত হয়। (উদাহরণ: পূর্বে 'পুস্তক', বর্তমানে 'বই')
ঙ) ভাষা নিয়মবদ্ধ: প্রত্যেক ভাষার নিজস্ব ব্যাকরণ রয়েছে। সেই নিয়ম অনুসারেই ভাষা ব্যবহার করতে হয়।
চ) ভাষা সংস্কৃতির বাহক: একটি জাতির ইতিহাস, সাহিত্য, ধর্ম, ঐতিহ্য ও সংস্কৃতি ভাষার মাধ্যমে সংরক্ষিত থাকে।
ছ) ভাষা অর্জিত: ভাষা জন্মগত নয়। মানুষ পরিবার ও সমাজে বসবাস করে ভাষা শেখে।
জ) ভাষা যোগাযোগের মাধ্যম: মানুষ ভাষার সাহায্যে তথ্য আদান-প্রদান করে।

৩. ভাষার গুরুত্ব
মানবজীবনে ভাষার গুরুত্ব অপরিসীম।
ক) ভাব প্রকাশে সাহায্য করে: মানুষ নিজের মনের কথা প্রকাশ করতে পারে।
খ) শিক্ষা অর্জনের মাধ্যম: বই পড়া, লেখা, পাঠদান, পরীক্ষা—সবই ভাষার মাধ্যমে হয়।
গ) জ্ঞান সংরক্ষণ: বই, পত্রিকা, গবেষণা, ইতিহাস—সব ভাষার মাধ্যমে সংরক্ষিত হয়।
ঘ) সামাজিক সম্পর্ক গড়ে তোলে: ভাষা মানুষের পারস্পরিক সম্পর্ক দৃঢ় করে।
ঙ) সংস্কৃতি রক্ষা করে: লোকগান, কবিতা, গল্প, নাটক, প্রবাদ—সব ভাষার মাধ্যমে টিকে থাকে।
চ) রাষ্ট্র পরিচালনায় সহায়ক: আইন, প্রশাসন, শিক্ষা, বিচার—সব ক্ষেত্রেই ভাষা ব্যবহৃত হয়।
ছ) বিজ্ঞান ও প্রযুক্তির উন্নয়ন: নতুন জ্ঞান ও আবিষ্কার ভাষার মাধ্যমে ছড়িয়ে পড়ে।

৪. ভাষার উৎপত্তি সম্পর্কে ধারণা
ভাষা কীভাবে সৃষ্টি হয়েছে, তা নিয়ে বিভিন্ন মতবাদ রয়েছে।
১. ঐশ্বরিক মতবাদ: এই মতবাদ অনুযায়ী ভাষা ঈশ্বরপ্রদত্ত।
২. অনুকরণ মতবাদ: মানুষ প্রকৃতির বিভিন্ন শব্দ অনুকরণ করে ভাষা সৃষ্টি করেছে। (উদাহরণ: কাক ➔ কা কা, কোকিল ➔ কুহু, ঝরনা ➔ ঝরঝর)
৩. আবেগ মতবাদ: আনন্দ, দুঃখ, ভয়, বিস্ময় ইত্যাদি আবেগ প্রকাশ করতে গিয়ে ভাষার সৃষ্টি হয়েছে। (উদাহরণ: আহ!, উফ!, ওহ!)
৪. শ্রম মতবাদ: একসঙ্গে কাজ করার সময় পারস্পরিক সমন্বয়ের জন্য ভাষার সৃষ্টি হয়েছে।
৫. সামাজিক মতবাদ: মানুষ সমাজে বসবাস করতে গিয়ে যোগাযোগের প্রয়োজন অনুভব করে। সেই প্রয়োজন থেকেই ভাষার জন্ম। (বর্তমানে অধিকাংশ ভাষাবিজ্ঞানী এই মতবাদকে বেশি গ্রহণযোগ্য মনে করেন।)

৫. ভাষার কাজ
ভাষার প্রধান কাজগুলো হলো—
১. ভাব প্রকাশ করা
২. তথ্য আদান-প্রদান
৩. শিক্ষা প্রদান
৪. সাহিত্য সৃষ্টি
৫. সংস্কৃতি সংরক্ষণ
৬. গবেষণা ও জ্ঞান বিস্তার
৭. প্রশাসনিক কাজ

৬. ভাষা ও সমাজের সম্পর্ক
ভাষা ও সমাজ একে অপরের সঙ্গে গভীরভাবে সম্পর্কিত।
সমাজ ছাড়া ভাষার বিকাশ সম্ভব নয়, ভাষা ছাড়া সমাজের উন্নয়ন অসম্ভব।
সমাজের পরিবর্তনের সঙ্গে ভাষারও পরিবর্তন ঘটে।
নতুন প্রযুক্তির কারণে ভাষায় নতুন শব্দ যুক্ত হয় (উদাহরণ: মোবাইল, ইন্টারনেট, অ্যাপ, অনলাইন, ক্লাউড, কৃত্রিম বুদ্ধিমত্তা AI)।

৭. উদাহরণ
উদাহরণ–১: রহিম বলল, "আমি আজ স্কুলে যাব।" (এখানে ভাষার মাধ্যমে সে নিজের ইচ্ছা প্রকাশ করেছে)
উদাহরণ–২: শিক্ষক বললেন, "আগামীকাল পরীক্ষা অনুষ্ঠিত হবে।" (এখানে ভাষা তথ্য প্রদানের মাধ্যম)
উদাহরণ–৩: মা বললেন, "খাবার খেয়ে পড়তে বসো।" (এখানে ভাষা নির্দেশ দেওয়ার কাজে ব্যবহৃত হয়েছে)
উদাহরণ–৪: কবি লিখলেন— "আমার সোনার বাংলা, আমি তোমায় ভালোবাসি।" (এখানে ভাষা সাহিত্য ও আবেগ প্রকাশের মাধ্যম)

