            explanation = """
১. বাংলা ভাষার পরিচয়
বাংলা ভাষা (Bangla/Bengali) পৃথিবীর অন্যতম সমৃদ্ধ, প্রাচীন ও মধুর ভাষা। এটি বাংলাদেশের রাষ্ট্রভাষা এবং ভারতের পশ্চিমবঙ্গ, ত্রিপুরা ও আসামের কিছু অঞ্চলের অন্যতম সরকারি ভাষা। বাংলা ভাষা ইন্দো-ইউরোপীয় ভাষাপরিবারের অন্তর্গত এবং ইন্দো-আর্য ভাষাশাখার একটি প্রধান ভাষা।

বাংলা ভাষায় হাজার বছরের সাহিত্য-ঐতিহ্য রয়েছে। চর্যাপদ থেকে শুরু করে আধুনিক সাহিত্য পর্যন্ত বাংলা ভাষা জ্ঞান, সাহিত্য, সংস্কৃতি ও ইতিহাসের এক বিশাল ভাণ্ডার।
বর্তমানে বিশ্বে প্রায় ৩০ কোটিরও বেশি মানুষ বাংলা ভাষায় কথা বলে। মাতৃভাষাভাষীর সংখ্যার দিক থেকে বাংলা বিশ্বের অন্যতম বৃহৎ ভাষা।

বাংলা ভাষার পরিচয়ের প্রধান বৈশিষ্ট্য:
- বাংলাদেশের রাষ্ট্রভাষা।
- বিশ্বের অন্যতম বহুল ব্যবহৃত ভাষা।
- সমৃদ্ধ সাহিত্য ও সংস্কৃতির ভাষা।
- নিজস্ব বাংলা লিপি রয়েছে।
- হাজার বছরের ইতিহাস বহন করে।
- আন্তর্জাতিক মাতৃভাষা দিবসের সঙ্গে সরাসরি সম্পর্কিত একমাত্র ভাষা।

২. বাংলা ভাষার উৎপত্তি
বাংলা ভাষার উৎপত্তি বহু শতাব্দী আগে।
ভাষাবিজ্ঞানীদের মতে বাংলা ভাষা এসেছে—
সংস্কৃত ➔ প্রাকৃত ➔ অপভ্রংশ ➔ প্রাচীন বাংলা ➔ মধ্য বাংলা ➔ আধুনিক বাংলা

উৎপত্তির ধাপ:
১. সংস্কৃত: প্রাচীন ভারতের সাহিত্য ও ধর্মীয় ভাষা ছিল সংস্কৃত।
২. প্রাকৃত: সাধারণ মানুষের মুখের ভাষা ছিল প্রাকৃত।
৩. অপভ্রংশ: প্রাকৃত ভাষা ধীরে ধীরে পরিবর্তিত হয়ে অপভ্রংশে রূপ নেয়।
৪. প্রাচীন বাংলা (খ্রিস্টীয় ১০ম–১২ম শতাব্দী): চর্যাপদ বাংলা ভাষার প্রাচীনতম নিদর্শন।
৫. মধ্য বাংলা (১৩৫০–১৮০০ খ্রিস্টাব্দ): এই সময়ে মঙ্গলকাব্য, বৈষ্ণব পদাবলি, অনুবাদ সাহিত্য রচিত হয়।
৬. আধুনিক বাংলা (ঊনবিংশ শতাব্দী থেকে বর্তমান): বিদ্যাসাগর, বঙ্কিমচন্দ্র, রবীন্দ্রনাথ, নজরুল প্রমুখ বাংলা ভাষাকে সমৃদ্ধ করেন।

৩. বাংলা ভাষার বিস্তার
বাংলাদেশ ছাড়াও ভারতের পশ্চিমবঙ্গ, ত্রিপুরা ও আসামে সরকারি ভাষা। বিশ্বজুড়ে প্রবাসী বাঙালিরা যুক্তরাজ্য, যুক্তরাষ্ট্র, কানাডা, ইতালি, মধ্যপ্রাচ্য, মালয়েশিয়া, সিঙ্গাপুর, অস্ট্রেলিয়া প্রভৃতি দেশে বাংলা ভাষা ব্যবহার করেন।

৪. বাংলা ভাষার বর্তমান অবস্থা
শিক্ষা, সাহিত্য, গণমাধ্যম (সংবাদপত্র, টিভি, রেডিও), এবং প্রযুক্তিতে (মোবাইল অ্যাপ, কৃত্রিম বুদ্ধিমত্তা AI, ই-বুক, অনুবাদ সফটওয়্যার) বাংলা ভাষার ব্যাপক ব্যবহার রয়েছে।

৫. বাংলা ভাষার মর্যাদা
বাংলাদেশের সংবিধান অনুযায়ী বাংলা রাষ্ট্রভাষা। ১৯৫২ সালের ভাষা আন্দোলনে আত্মত্যাগ, রবীন্দ্রনাথ ঠাকুরের নোবেল পুরস্কার অর্জন এবং ১৯৯৯ সালে ইউনেস্কো কর্তৃক ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস হিসেবে স্বীকৃতির মাধ্যমে বাংলা ভাষা আন্তর্জাতিক মর্যাদা লাভ করেছে।

৬. আন্তর্জাতিক মাতৃভাষা দিবস
- ইতিহাস: ১৯৫২ সালের ২১ ফেব্রুয়ারি বাংলা ভাষার দাবিতে শহীদ হন সালাম, বরকত, রফিক, জব্বার, শফিউরসহ অনেকে।
- ইউনেস্কো ঘোষণা: ১৯৯৯ সালের ১৭ নভেম্বর ইউনেস্কো ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস হিসেবে ঘোষণা করে। ২০০০ সাল থেকে সারা বিশ্বে দিবসটি পালিত হচ্ছে।

৭. অনুশীলনী
