২. প্রাচীন বাংলা (খ্রিস্টীয় ৯৫০–১২০০)
- পরিচয়: প্রাচীন বাংলা বাংলা ভাষার প্রথম বিকাশপর্ব। অপভ্রংশ থেকে স্বতন্ত্র ভাষা হিসেবে গড়ে ওঠে।
- প্রধান সাহিত্য: চর্যাপদ (বাংলা ভাষার সর্বপ্রাচীন সাহিত্য নিদর্শন, ৪৭টি পদ, রচয়িতা লুইপা, কাহ্নপা, ভুসুকুপা, শবরপা প্রমুখ বৌদ্ধ সিদ্ধাচার্য)।

৩. মধ্য বাংলা (খ্রিস্টীয় ১২০১–১৮০০)
- পরিচয়: বাংলা ভাষা সাধারণ মানুষের ভাষায় পরিণত হয়। আরবি ও ফারসি শব্দ প্রবেশ করে।
- সাহিত্যধারা: মঙ্গলকাব্য (মনসামঙ্গল, চণ্ডীমঙ্গল, ধর্মমঙ্গল), বৈষ্ণব পদাবলি, অনুবাদ সাহিত্য (রামায়ণ, মহাভারত)।
- উল্লেখযোগ্য সাহিত্যিক: কৃত্তিবাস ওঝা, কাশীরাম দাস, মুকুন্দরাম চক্রবর্তী, ভারতচন্দ্র রায়গুণাকর, আলাওল।

৪. আধুনিক বাংলা (১৮০১–বর্তমান)
- পরিচয়: ঊনবিংশ শতাব্দী থেকে আধুনিক বাংলা ভাষার সূচনা। ব্যাকরণ, মানক বানান, গদ্য ও সংবাদপত্রের প্রচলন।
- উল্লেখযোগ্য সাহিত্যিক: ঈশ্বরচন্দ্র বিদ্যাসাগর (গদ্যের জনক), বঙ্কিমচন্দ্র চট্টোপাধ্যায়, রবীন্দ্রনাথ ঠাকুর (১৯১৩ সালে সাহিত্যে নোবেল বিজয়ী), কাজী নজরুল ইসলাম (বিদ্রোহী কবি), শরৎচন্দ্র, জীবনানন্দ দাশ, জসীমউদ্দীন প্রমুখ।

৫. ভাষার বিবর্তন
ভাষার পরিবর্তন ঘটে সামাজিক পরিবর্তন, প্রযুক্তি, বিদেশি ভাষা (আরবি, ফারসি, ইংরেজি) ও উচ্চারণের কারণে।

৬. যুগভাগ ও ঐতিহাসিক মাইলফলক
- ৯৫০–১২০০: প্রাচীন বাংলা ও চর্যাপদ
- ১২০১–১৮০০: মধ্য বাংলা ও মঙ্গলকাব্য
- ১৮০১–বর্তমান: আধুনিক বাংলা ও গদ্যের বিকাশ
- ১৯১৩: রবীন্দ্রনাথের নোবেল পুরস্কার
- ১৯৫২: ভাষা আন্দোলন
- ১৯৭১: বাংলাদেশের স্বাধীনতা
- ১৯৯৯: ইউনেস্কো কর্তৃক ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস ঘোষণা।

৭. অনুশীলনী
