উৎপত্তির ধারা: ইন্দো-ইউরোপীয় ➔ ইন্দো-ইরানীয় ➔ ভারতীয় আর্য ➔ প্রাকৃত ➔ অপভ্রংশ ➔ বাংলা ভাষা।

২. ইন্দো-ইউরোপীয় ভাষা
বিশ্বের সবচেয়ে বড় ভাষাপরিবার। বাংলা, হিন্দি, উর্দু, ইংরেজি, জার্মান, ফরাসি, স্প্যানিশ, ফারসি ইত্যাদি ভাষা এই পরিবারের অন্তর্গত।

৩. ইন্দো-ইরানীয় ভাষা
ইন্দো-ইউরোপীয় পরিবারের একটি গুরুত্বপূর্ণ শাখা। এটি দুই ভাগে বিভক্ত:
১. ইরানীয় ভাষা (ফারসি, পশতু)
২. ভারতীয় আর্য ভাষা (বাংলা, হিন্দি, অসমীয়া, মারাঠি, ওড়িয়া, গুজরাটি ইত্যাদি)

৪. ভারতীয় আর্য ভাষা
- প্রাচীন: বৈদিক সংস্কৃত ও সংস্কৃত।
- মধ্য: প্রাকৃত ও পালি।
- নব: বাংলা, হিন্দি, উর্দু, অসমীয়া, মারাঠি ইত্যাদি।

৫. প্রাকৃত ও অপভ্রংশ
- প্রাকৃত: সাধারণ মানুষের মুখের ভাষা (বাংলা মূলত মাগধী প্রাকৃত থেকে এসেছে)।
- অপভ্রংশ: প্রাকৃতের পরিবর্তিত রূপ (মাগধী অপভ্রংশ)।

৬. বাংলা ভাষার সৃষ্টি ও বিদেশি শব্দের প্রভাব
বাংলা ভাষা বিকাশের পথে বিভিন্ন ভাষা থেকে বহু শব্দ গ্রহণ করেছে:
- সংস্কৃত: বিদ্যালয়, বন্ধু, সমাজ
- আরবি: খবর, আদালত, হিসাব
- ফারসি: বাজার, দরবার, খরচ
- পর্তুগিজ: আলমারি, জানালা, চাবি, সাবান
- ইংরেজি: স্কুল, কলেজ, ট্রেন, মোবাইল, কম্পিউটার

