ইন্দো-ইউরোপীয় ➔ ইন্দো-ইরানীয় ➔ ভারতীয় আর্য ➔ সংস্কৃত ➔ মাগধী প্রাকৃত ➔ মাগধী অপভ্রংশ ➔ প্রাচীন বাংলা ➔ মধ্য বাংলা ➔ আধুনিক বাংলা।

