- প্রাচীন বাংলা (৯৫০–১২০০): চর্যাপদ, বৌদ্ধ ধর্মের প্রভাব, সংক্ষিপ্ত ও সহজ ভাষা।
- মধ্য বাংলা (১২০১–১৮০০): মঙ্গলকাব্য, বৈষ্ণব সাহিত্য, অনুবাদ সাহিত্য, আরবি-ফারসি শব্দের ব্যবহার।
- আধুনিক বাংলা (১৮০১–বর্তমান): গদ্যের বিস্তার, মানক ব্যাকরণ, প্রযুক্তি ও আন্তর্জাতিক যোগাযোগ।

৪. পরিবর্তনের কারণসমূহ
- সামাজিক ও রাজনৈতিক পরিবর্তন।
- ধর্মীয় প্রভাব (সংস্কৃত, আরবি, ফারসি শব্দ)।
- বিদেশি ভাষার প্রভাব (পর্তুগিজ, ইংরেজি)।
- সাহিত্য ও শিক্ষা।
- বিজ্ঞান ও প্রযুক্তি (সফটওয়্যার, অ্যাপ, ডাউনলোড, কৃত্রিম বুদ্ধিমত্তা AI, ক্লাউড)।
- গণমাধ্যম ও বিশ্বায়ন।

৫. উদাহরণ
- সংস্কৃত থেকে পরিবর্তন: গৃহ ➔ ঘর; অগ্নি ➔ আগুন; পুস্তক ➔ বই।
- প্রযুক্তির প্রভাবে নতুন শব্দ: ই-মেইল, এসএমএস, ভিডিও কল, অনলাইন মিটিং।

