২. কথ্য ভাষা
যে ভাষায় মানুষ দৈনন্দিন জীবনে মুখে মুখে কথা বলে (সহজ, সাবলীল, দ্রুত ভাব প্রকাশ)।
উদাহরণ: "তুই কই যাস?" / "কোথায় যাচ্ছো?"

৩. লিখিত ভাষা
যে ভাষা লিখে প্রকাশ করা হয়—বই, সংবাদপত্র, সাহিত্য, সরকারি নথি ইত্যাদিতে।
উদাহরণ: "বাংলা আমাদের মাতৃভাষা।"

৪. আঞ্চলিক ভাষা
বাংলা ভাষার যে রূপ নির্দিষ্ট কোনো অঞ্চলে প্রচলিত (ঢাকা, চট্টগ্রাম, সিলেট, নোয়াখালী, বরিশাল, রাজশাহী ইত্যাদি)।

৫. উপভাষা (Dialect)
একটি ভাষার আঞ্চলিক বা সামাজিক বিশেষ রূপ (যেমন: রাঢ়ী, বরেন্দ্রী, বঙ্গালী, কামরূপী, ঝাড়খণ্ডী)।

৬. মান ভাষা (Standard Language)
শিক্ষা, সাহিত্য, গণমাধ্যম, প্রশাসন ও আনুষ্ঠানিক যোগাযোগে সর্বজনগ্রাহ্য ব্যাকরণসম্মত আদর্শ রূপ।
উদাহরণ: "আমি আজ বিদ্যালয়ে যাব।"

৭. তুলনা সারণি
- কথ্য ভাষা: দৈনন্দিন কথাবলা, শিথিল ব্যাকরণ।
- আঞ্চলিক ভাষা: নির্দিষ্ট অঞ্চলের জনগণের ব্যবহার।
- মান ভাষা: সারা দেশে শিক্ষা, সাহিত্য ও প্রশাসনে ব্যবহৃত আদর্শ ব্যাকরণসম্মত রূপ।

৮. অনুশীলনী
ক) শূন্যস্থান পূরণ করো:
১. মুখে মুখে ব্যবহৃত ভাষাকে __________ ভাষা বলে।
