২. সাধু ভাষা
- সংজ্ঞা: যে ভাষার রীতি ব্যাকরণসম্মত, গম্ভীর, মার্জিত এবং ক্রিয়াপদ ও সর্বনামের পূর্ণরূপ ব্যবহৃত হয়।
- বৈশিষ্ট্য: ক্রিয়াপদের পূর্ণরূপ (করিতেছি, যাইতেছি, বলিলাম), তৎসম শব্দ বেশি, বাক্যের দৈর্ঘ্য বেশি।
- উদাহরণ: "আমি বিদ্যালয়ে গিয়াছিলাম। সে আমাকে একটি পুস্তক দিয়াছিল।"

৩. চলিত ভাষা
- সংজ্ঞা: যে ভাষার রীতি সহজ, স্বাভাবিক, সংক্ষিপ্ত এবং দৈনন্দিন জীবনে ব্যবহৃত হয়।
- বৈশিষ্ট্য: ক্রিয়াপদের সংক্ষিপ্ত রূপ (করছি, যাচ্ছি, বললাম), সংক্ষিপ্ত সর্বনাম (তারা, তাদের), সহজ ও সাবলীল।
- উদাহরণ: "আমি বিদ্যালয়ে গিয়েছিলাম। সে আমাকে একটি বই দিয়েছিল।"

৪. সাধু ও চলিত ভাষার পার্থক্য
- সাধু: বলিতেছি ➔ চলিত: বলছি
- সাধু: করিবে ➔ চলিত: করবে
- সাধু: তাহারা ➔ চলিত: তারা
- সাধু: পুস্তক ➔ চলিত: বই
- সাধু: সহিত ➔ চলিত: সঙ্গে

৫. রূপান্তর অনুশীলনী
সাধু: "আমি তাহার সহিত কথা বলিয়াছি।" ➔ চলিত: "আমি তার সঙ্গে কথা বলেছি।"

