- সহজ, স্পষ্ট ও সুনির্দিষ্ট অর্থ প্রকাশ করে।

৩. প্রমিত ভাষার ব্যবহারক্ষেত্র
- শিক্ষা: বিদ্যালয়, কলেজ, বিশ্ববিদ্যালয় ও পাঠ্যপুস্তক।
