- গণমাধ্যম: সংবাদপত্র, টেলিভিশন, রেডিও, অনলাইন সংবাদ।
- সাহিত্য ও বিজ্ঞান: গল্প, উপন্যাস, প্রবন্ধ, গবেষণা, প্রযুক্তি।

৪. গুরুত্ব
- জাতীয় ঐক্য প্রতিষ্ঠা করে।
- শিক্ষার মান উন্নয়ন করে।
- সরকারি কাজ ও যোগাযোগ সহজ করে।
- ভাষার শুদ্ধতা ও আন্তর্জাতিক মর্যাদা রক্ষা করে।

