২. উপভাষার বৈশিষ্ট্য
- মূল ভাষারই অংশ, পৃথক কোনো ভাষা নয়।
- অঞ্চলভেদে উচ্চারণ, শব্দভাণ্ডার ও বাক্যরীতিতে পার্থক্য থাকে।
- স্থানীয় ইতিহাস, লোকসংগীত ও লোকসংস্কৃতির বাহক।

