- নোয়াখালী: "আইজ বাজারে যামু" (আজ বাজারে যাব)।
- বরিশাল: "মুই যামু" (আমি যাব)।
- রাজশাহী: "কই যাইছ?" (কোথায় যাচ্ছ?)
- রংপুর: "মুই বাড়ি যাম" (আমি বাড়ি যাব)।

৪. উপভাষার গুরুত্ব
- ভাষার বৈচিত্র্য সংরক্ষণ করে।
- লোকসাহিত্য ও লোক ঐতিহ্য টিকিয়ে রাখে।
- অঞ্চলভেদে ভাষার সমৃদ্ধি ঘটায়।

৫. উপভাষা ও প্রমিত ভাষার পার্থক্য
