২. রাষ্ট্রভাষা
- সংজ্ঞা: রাষ্ট্র পরিচালনা, প্রশাসন, আইন, বিচার ও সরকারি কাজে ব্যবহারের জন্য সংবিধান দ্বারা স্বীকৃত ভাষা।
- বাংলাদেশের রাষ্ট্রভাষা: সংবিধানের ৩ নম্বর অনুচ্ছেদ অনুযায়ী 'বাংলা'।

৩. জাতীয় ভাষা
- একটি জাতির ইতিহাস, ঐতিহ্য, সংস্কৃতি ও গৌরবের প্রতীক হিসেবে স্বীকৃত ভাষা।

৪. আন্তর্জাতিক ভাষা
- বিশ্বের বহু দেশের মানুষের মধ্যে আন্তর্জাতিক যোগাযোগ, ব্যবসা, শিক্ষা, বিজ্ঞান ও প্রযুক্তিতে ব্যবহৃত ভাষা (যেমন: ইংরেজি)।

৫. তুলনামূলক সারণি
- মাতৃভাষা: পরিবার ও স্বাভাবিক শিক্ষা।
- রাষ্ট্রভাষা: সরকারি প্রশাসন ও সংবিধান।
- জাতীয় ভাষা: জাতীয় সংহতি ও সংকল্প।
- আন্তর্জাতিক ভাষা: বিশ্বব্যাপী যোগাযোগ।

