            explanation = """
১. ভাষা আন্দোলন
পরিচয়
ভাষা আন্দোলন হলো বাংলা ভাষাকে রাষ্ট্রভাষার মর্যাদা দেওয়ার দাবিতে পূর্ব বাংলার (বর্তমান বাংলাদেশ) ছাত্র, শিক্ষক, বুদ্ধিজীবী ও সাধারণ মানুষের গণআন্দোলন।
এই আন্দোলনের মাধ্যমে বাঙালি জাতি তাদের মাতৃভাষার অধিকার প্রতিষ্ঠা করে। ভাষা আন্দোলন শুধু ভাষার জন্য সংগ্রাম নয়; এটি ছিল বাঙালির আত্মপরিচয়, সংস্কৃতি, অধিকার ও স্বাধীনতার চেতনার সূচনা।
ভাষা আন্দোলনের সবচেয়ে গুরুত্বপূর্ণ ঘটনা ঘটে ১৯৫২ সালের ২১ ফেব্রুয়ারি।

২. ভাষা আন্দোলনের পটভূমি
দেশভাগ
১৯৪৭ সালে ভারত বিভক্ত হয়ে দুটি রাষ্ট্র গঠিত হয়—
ভারত
পাকিস্তান
পাকিস্তানের দুটি অংশ ছিল—
পূর্ব পাকিস্তান (বর্তমান বাংলাদেশ)
পশ্চিম পাকিস্তান (বর্তমান পাকিস্তান)
পূর্ব পাকিস্তানের অধিকাংশ মানুষের মাতৃভাষা ছিল বাংলা।

ভাষা নিয়ে বিরোধ
পাকিস্তানের কেন্দ্রীয় সরকার উর্দুকে একমাত্র রাষ্ট্রভাষা করার উদ্যোগ নেয়। এতে পূর্ব পাকিস্তানের মানুষ ক্ষুব্ধ হয়, কারণ দেশের সংখ্যাগরিষ্ঠ মানুষের ভাষা ছিল বাংলা।

৩. ১৯৪৮ সালের ঘটনা
১৯৪৮ সাল ছিল ভাষা আন্দোলনের সূচনাপর্ব।
২৩ ফেব্রুয়ারি ১৯৪৮
পাকিস্তানের গণপরিপরিষদে বাংলাকে রাষ্ট্রভাষা করার দাবি উত্থাপন করা হয়।
১১ মার্চ ১৯৪৮
বাংলাকে রাষ্ট্রভাষা করার দাবিতে ধর্মঘট ও আন্দোলন শুরু হয়।
বহু ছাত্রনেতা গ্রেপ্তার হন।
আন্দোলন সারা পূর্ব বাংলায় ছড়িয়ে পড়ে।
২১ মার্চ ১৯৪৮
পাকিস্তানের গভর্নর জেনারেল মুহাম্মদ আলী জিন্নাহ ঢাকায় এসে ঘোষণা করেন—
"উর্দুই হবে পাকিস্তানের একমাত্র রাষ্ট্রভাষা।"
এই ঘোষণায় ছাত্রসমাজ ও সাধারণ মানুষের মধ্যে তীব্র প্রতিবাদ সৃষ্টি হয়।
২৪ মার্চ ১৯৪৮
ঢাকা বিশ্ববিদ্যালয়ের সমাবর্তনে জিন্নাহ আবারও উর্দুকে একমাত্র রাষ্ট্রভাষা করার কথা বলেন।
ছাত্ররা এর প্রতিবাদ জানান।

১৯৪৮ সালের ঘটনার গুরুত্ব
ভাষা আন্দোলনের সূচনা হয়।
ছাত্রসমাজ সংগঠিত হয়।
বাংলা ভাষার দাবিতে গণআন্দোলনের ভিত্তি তৈরি হয়।

৪. ১৯৫২ সালের ভাষা আন্দোলন
পটভূমি
১৯৫২ সালে পাকিস্তান সরকার উর্দুকেই রাষ্ট্রভাষা করার সিদ্ধান্তে অটল থাকে।
বাংলা ভাষার দাবিতে ছাত্রসমাজ নতুন করে আন্দোলন শুরু করে।
২১ ফেব্রুয়ারি ১৯৫২
সরকার ঢাকায় ১৪৪ ধারা জারি করে, অর্থাৎ সভা-সমাবেশ নিষিদ্ধ করা হয়।
কিন্তু ঢাকা বিশ্ববিদ্যালয়, মেডিকেল কলেজ ও অন্যান্য শিক্ষাপ্রতিষ্ঠানের ছাত্ররা ১৪৪ ধারা ভঙ্গ করে মিছিল বের করেন।
পুলিশ মিছিলে গুলি চালায়।

ভাষা শহীদ
পুলিশের গুলিতে বহু মানুষ শহীদ হন। তাঁদের মধ্যে উল্লেখযোগ্য—
আবুল বরকত
আব্দুস সালাম
আব্দুল জব্বার
রফিকউদ্দিন আহমেদ (রফিক)
শফিউর রহমান
এছাড়াও আরও অনেকে আহত ও শহীদ হন।

আন্দোলনের ফলাফল
বাংলা ভাষার দাবিতে আন্দোলন আরও শক্তিশালী হয়।
সারা দেশে প্রতিবাদের ঝড় ওঠে।
শেষ পর্যন্ত বাংলা রাষ্ট্রভাষার স্বীকৃতি লাভ করে।
ভাষা আন্দোলন ভবিষ্যতের স্বাধীনতা আন্দোলনকে অনুপ্রাণিত করে।

৫. শহীদ দিবস
পরিচয়
প্রতি বছর ২১ ফেব্রুয়ারি ভাষা আন্দোলনের শহীদদের স্মরণে শহীদ দিবস পালন করা হয়।
শহীদ দিবসে পালনীয় কর্মসূচি
শহীদ মিনারে ফুল দেওয়া
প্রভাতফেরি
খালি পায়ে শহীদ মিনারে যাওয়া
আলোচনা সভা
সাংস্কৃতিক অনুষ্ঠান
কবিতা আবৃত্তি
ভাষা আন্দোলনভিত্তিক প্রদর্শনী

শহীদ মিনার
ভাষা আন্দোলনের শহীদদের স্মরণে নির্মিত স্মৃতিস্তম্ভকে শহীদ মিনার বলা হয়।
এটি ভাষা আন্দোলনের আত্মত্যাগ ও গৌরবের প্রতীক।

৬. একুশে ফেব্রুয়ারি
পরিচয়
একুশে ফেব্রুয়ারি বাঙালি জাতির গৌরব, আত্মত্যাগ ও ভাষাপ্রেমের প্রতীক।
১৯৫২ সালের এই দিনে বাংলা ভাষার মর্যাদা প্রতিষ্ঠার জন্য ছাত্র-জনতা জীবন উৎসর্গ করেন।
আন্তর্জাতিক স্বীকৃতি
১৯৯৯ সালের ১৭ নভেম্বর ইউনেস্কো ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস হিসেবে ঘোষণা করে।
২০০০ সাল থেকে বিশ্বের বিভিন্ন দেশে দিবসটি পালিত হচ্ছে।

একুশের চেতনা
মাতৃভাষার প্রতি ভালোবাসা
ভাষার অধিকার প্রতিষ্ঠা
অন্যায়ের বিরুদ্ধে প্রতিবাদ
জাতীয় ঐক্য
আত্মত্যাগের শিক্ষা
সংস্কৃতির প্রতি শ্রদ্ধা

৭. ভাষা আন্দোলনের গুরুত্ব
ভাষা আন্দোলনের গুরুত্ব অত্যন্ত ব্যাপক।
