২. ১৯৫২ সালের ভাষা আন্দোলনের ঘটনাপ্রবাহ বিস্তারিত বর্ণনা করো।
৩. ভাষা আন্দোলনের গুরুত্ব ও একুশের চেতনা ব্যাখ্যা করো।
