অধ্যায়ের সারসংক্ষেপ:
- ভাষা আন্দোলন ছিল বাংলা ভাষাকে রাষ্ট্রভাষার মর্যাদা দেওয়ার দাবিতে পরিচালিত ঐতিহাসিক আন্দোলন।
- ১৯৪৮ সালে বাংলাকে রাষ্ট্রভাষা করার দাবিতে আন্দোলনের সূচনা হয় এবং জিন্নাহ উর্দুকে একমাত্র রাষ্ট্রভাষা ঘোষণা করেন।
- ১৯৫২ সালের ২১ ফেব্রুয়ারি ১৪৪ ধারা ভঙ্গ করে ছাত্ররা মিছিল করলে পুলিশের গুলিতে সালাম, বরকত, রফিক, জব্বার, শফিউরসহ অনেকে শহীদ হন।
- ভাষা আন্দোলনের স্মরণে ২১ ফেব্রুয়ারি শহীদ দিবস পালন করা হয় এবং ১৯৯৯ সালে ইউনেস্কো এ দিনকে আন্তর্জাতিক মাতৃভাষা দিবস হিসেবে ঘোষণা করে।
