            explanation = """
১. আন্তর্জাতিক মাতৃভাষা দিবস
পরিচয়
আন্তর্জাতিক মাতৃভাষা দিবস (International Mother Language Day) প্রতি বছর ২১ ফেব্রুয়ারি বিশ্বব্যাপী পালিত হয়। এই দিবসের উদ্দেশ্য হলো মাতৃভাষার মর্যাদা রক্ষা, ভাষাগত বৈচিত্র্য সংরক্ষণ এবং পৃথিবীর সব ভাষার প্রতি সম্মান প্রদর্শন।
এই দিবসের মূল অনুপ্রেরণা এসেছে ১৯৫২ সালের বাংলা ভাষা আন্দোলন থেকে, যেখানে বাংলা ভাষার মর্যাদা প্রতিষ্ঠার জন্য বহু মানুষ জীবন উৎসর্গ করেছিলেন।
বর্তমানে বিশ্বের বিভিন্ন দেশে নানা আয়োজনের মাধ্যমে দিবসটি পালন করা হয়।

২. আন্তর্জাতিক মাতৃভাষা দিবসের ইতিহাস
ভাষা আন্দোলনের সূচনা
১৯৫২ সালের ২১ ফেব্রুয়ারি বাংলা ভাষাকে রাষ্ট্রভাষার মর্যাদা দেওয়ার দাবিতে ছাত্র-জনতা আন্দোলন করেন।
পুলিশের গুলিতে সালাম, বরকত, রফিক, জব্বার, শফিউরসহ অনেকেই শহীদ হন।
এই আত্মত্যাগ বিশ্ববাসীর কাছে মাতৃভাষার অধিকারের প্রতীক হয়ে ওঠে।

আন্তর্জাতিক স্বীকৃতির পথ
বাংলাদেশ দীর্ঘদিন ধরে ২১ ফেব্রুয়ারিকে আন্তর্জাতিকভাবে স্বীকৃতি দেওয়ার উদ্যোগ গ্রহণ করে।
অবশেষে ১৯৯৯ সালের ১৭ নভেম্বর ইউনেস্কো (UNESCO) ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস হিসেবে ঘোষণা করে।
২০০০ সাল থেকে বিশ্বের বিভিন্ন দেশে দিবসটি আনুষ্ঠানিকভাবে পালন করা হচ্ছে।

৩. UNESCO ঘোষণা
UNESCO কী?
UNESCO-এর পূর্ণরূপ হলো— United Nations Educational, Scientific and Cultural Organization (জাতিসংঘের শিক্ষা, বিজ্ঞান ও সংস্কৃতি বিষয়ক সংস্থা)।
UNESCO-এর ঘোষণা
১৯৯৯ সালের ১৭ নভেম্বর ইউনেস্কোর সাধারণ সম্মেলনে ২১ ফেব্রুয়ারিকে International Mother Language Day হিসেবে ঘোষণা করা হয়।
এই ঘোষণার ফলে—
- ভাষাগত বৈচিত্র্য সংরক্ষণের গুরুত্ব বৃদ্ধি পায়।
- মাতৃভাষার অধিকার বিশ্বব্যাপী স্বীকৃতি লাভ করে।
- ছোট ও বিলুপ্তপ্রায় ভাষা সংরক্ষণের উদ্যোগ বাড়ে।
- বিশ্বের মানুষ ভাষা আন্দোলনের ইতিহাস সম্পর্কে জানতে পারে।

