১. বাংলা ভাষার বৈশিষ্ট্য
পরিচয়
বাংলা ভাষা বিশ্বের অন্যতম সমৃদ্ধ, মধুর ও প্রাচীন ভাষাগুলোর একটি। এটি ইন্দো-ইউরোপীয় ভাষা পরিবারের অন্তর্গত এবং বর্তমানে বিশ্বের কোটি কোটি মানুষের মাতৃভাষা।
বাংলা ভাষার নিজস্ব ধ্বনি, বর্ণমালা, ব্যাকরণ, শব্দভাণ্ডার ও বাক্যগঠনের নিয়ম রয়েছে। এই বিশেষ গুণগুলোকেই বাংলা ভাষার বৈশিষ্ট্য বলা হয়।

বাংলা ভাষার প্রধান বৈশিষ্ট্য চারটি—
১. ধ্বনিগত বৈশিষ্ট্য
২. ব্যাকরণগত বৈশিষ্ট্য
৩. শব্দভাণ্ডারের বৈশিষ্ট্য
৪. বাক্যগঠনের বৈশিষ্ট্য

২. ধ্বনিগত বৈশিষ্ট্য
- নিজস্ব বর্ণমালা: ৫০টি মৌলিক বর্ণ (১১টি স্বরবর্ণ, ৩৯টি ব্যঞ্জনবর্ণ)।
- উচ্চারণের মাধুর্য: স্পষ্ট, কোমল ও শ্রুতিমধুর।
- যুক্তব্যঞ্জনের ব্যবহার: বিদ্যালয়, শ্রদ্ধা, লক্ষ্য, প্রজ্ঞা ইত্যাদি।
- নাসিক্য ধ্বনি: চাঁদ, বাঁশ, হাঁস ইত্যাদি।
- দীর্ঘ ও হ্রস্ব উচ্চারণ।

৩. ব্যাকরণগত বৈশিষ্ট্য
- কর্তা–কর্ম–ক্রিয়া (SOV) ক্রম: বাক্যের স্বাভাবিক ক্রম 'কর্তা + কর্ম + ক্রিয়া'। (উদাহরণ: আমি বই পড়ি।)
- লিঙ্গভেদ নেই: অধিকাংশ ক্রিয়াপদে পুরুষ ও স্ত্রীর জন্য আলাদা রূপ হয় না। (উদাহরণ: সে স্কুলে যায়।)
- বচনের ব্যবহার: একবচন ও বহুবচন (ছেলে/ছেলেরা, বই/বইগুলো)।
- কালভেদ: বর্তমান, অতীত ও ভবিষ্যৎ।
- বিভক্তি ও অনুসর্গের ব্যবহার: নদীতে, বাড়ির, সঙ্গে, জন্য ইত্যাদি।

৪. শব্দভাণ্ডারের বৈশিষ্ট্য
বাংলা শব্দভাণ্ডার ৫টি প্রধান উৎস থেকে সমৃদ্ধ:
- তৎসম: সূর্য, বিদ্যালয়, মাতা
- তদ্ভব: হাত, কান, ঘর, আগুন
- দেশি: ঢেঁকি, কুঁড়েঘর, লাঠি
- বিদেশি: বাজার, খবর, আলমারি, স্কুল, মোবাইল
- নতুন প্রযুক্তিভিত্তিক শব্দ: অ্যাপ, ক্লাউড, কৃত্রিম বুদ্ধিমত্তা AI

৫. বাক্যগঠনের বৈশিষ্ট্য
- কর্তা সাধারণত বাক্যের শুরুতে থাকে।
- ক্রিয়া সাধারণত বাক্যের শেষে থাকে। (উদাহরণ: আমি ভাত খাই।)
- বিভিন্ন প্রকার বাক্য: সরল, যৌগিক, জটিল, প্রশ্নবোধক, আদেশসূচক ও বিস্ময়সূচক।

৬. উদাহরণ সারণি
- ধ্বনি: চাঁদ, শ্রদ্ধা
- ব্যাকরণ: আমি বই পড়ি। (SOV)
- শব্দভাণ্ডার: বাজার, বিদ্যালয়, মোবাইল
- বাক্যগঠন: আমরা প্রতিদিন বিদ্যালয়ে যাই।

