২. তদ্ভব শব্দ
৩. দেশি শব্দ
৪. বিদেশি শব্দ
৫. মিশ্র শব্দ

২. তৎসম শব্দ
- সংজ্ঞা: সংস্কৃত ভাষা থেকে কোনো পরিবর্তন ছাড়াই সরাসরি বাংলা ভাষায় গৃহীত শব্দ। ('তৎ' = তার, 'সম' = সমান)
- উদাহরণ: সূর্য, চন্দ্র, বিদ্যালয়, পুস্তক, মাতা, পিতা, অগ্নি, জল, রাত্রি, গৃহ।

৩. তদ্ভব শব্দ
- সংজ্ঞা: সংস্কৃত ভাষার শব্দ প্রাকৃতের মাধ্যমে পরিবর্তিত হয়ে বাংলা ভাষায় যে রূপ ধারণ করেছে। ('তদ্' = তা, 'ভব' = উৎপন্ন)
- উদাহরণ: হস্ত ➔ হাত, কর্ণ ➔ কান, গৃহ ➔ ঘর, অগ্নি ➔ আগুন, দন্ত ➔ দাঁত, চক্ষু ➔ চোখ।

৪. দেশি শব্দ
- সংজ্ঞা: বাংলার আদি ও নিজস্ব জনগোষ্ঠীর ভাষা থেকে আগত শব্দ।
- উদাহরণ: ঢেঁকি, ঝুড়ি, কুঁড়েঘর, লাঠি, খোকা, খুকি, ডোবা, বাঁশ, পুকুর, কাদা।

৫. বিদেশি শব্দ
- সংজ্ঞা: রাজনৈতিক, ধর্মীয়, বাণিজ্যিক ও সামাজিক কারণে অন্য দেশের ভাষা থেকে বাংলা ভাষায় গৃহীত শব্দ।
- উদাহরণ:
  - আরবি: খবর, হিসাব, আদালত, দোয়া, নামায, রোজা
  - ফারসি: বাজার, দরবার, কাগজ, খরচ, জামা, চশমা
  - পর্তুগিজ: আলমারি, জানালা, সাবান, চাবি, বোতাম, বালতি
  - ইংরেজি: স্কুল, কলেজ, কম্পিউটার, মোবাইল, ইন্টারনেট, ট্রেন
  - তুর্কি: বেগম, উজির, সিপাহি, চাকর, তোপ

৬. মিশ্র শব্দ
- সংজ্ঞা: দুই বা ততোধিক ভিন্ন ভাষার শব্দ একত্রে মিলিত হয়ে গঠিত শব্দ।
- উদাহরণ:
  - ডাকঘর = ডাক (দেশি) + ঘর (তদ্ভব)
  - হেডমাস্টার = Head (ইংরেজি) + মাস্টার (ইংরেজি)
  - স্কুলঘর = স্কুল (ইংরেজি) + ঘর (তদ্ভব)
  - বইমেলা = বই (তদ্ভব) + মেলা (দেশি)

