১. বাংলা ভাষার লিপি
পরিচয়
লিপি হলো এমন এক ধরনের লিখন-পদ্ধতি, যার মাধ্যমে ভাষার ধ্বনিকে বিভিন্ন চিহ্ন বা বর্ণের সাহায্যে লিখে প্রকাশ করা হয়।
মানুষ প্রথমে ভাষার মাধ্যমে কথা বলতে শিখেছে। পরে সেই ভাষাকে স্থায়ীভাবে সংরক্ষণ করার জন্য লিপির সৃষ্টি হয়েছে।
বাংলা ভাষা লেখার জন্য যে লিপি ব্যবহার করা হয়, তাকে বাংলা লিপি বলা হয়।

২. লিপি কী?
সংজ্ঞা
যে লিখন-পদ্ধতির মাধ্যমে ভাষার ধ্বনিকে বর্ণ বা চিহ্নের সাহায্যে লিখে প্রকাশ করা হয়, তাকে লিপি বলে।
লিপির গুরুত্ব
- ভাষাকে লিখিত রূপ দেয়।
- জ্ঞান সংরক্ষণ করা যায়।
- সাহিত্য সৃষ্টি সম্ভব হয়।
- ইতিহাস সংরক্ষণ করা যায়।
- শিক্ষা ও গবেষণায় সহায়তা করে।
- প্রজন্ম থেকে প্রজন্মে জ্ঞান পৌঁছে যায়।

