দ্রষ্টব্য: বর্তমানে প্রচলিত বাংলা বর্ণমালায় ১১টি স্বরবর্ণ ও ৩৯টি ব্যঞ্জনবর্ণ শেখানো হয়।

বাংলা বর্ণমালার বৈশিষ্ট্য
- বাম থেকে ডানে লেখা হয়।
- প্রতিটি বর্ণের নির্দিষ্ট উচ্চারণ রয়েছে।
- স্বরবর্ণ ও ব্যঞ্জনবর্ণের সমন্বয়ে শব্দ গঠিত হয়।
- কারচিহ্ন ব্যবহারের মাধ্যমে স্বরের পরিবর্তন প্রকাশ করা হয়।
- যুক্তবর্ণ ব্যবহারের সুবিধা রয়েছে।

৪. লিপির ইতিহাস
প্রাচীন যুগ
মানুষ প্রথমে ছবি এঁকে ভাব প্রকাশ করত। একে চিত্রলিপি বলা হয়।
পরবর্তীতে ধীরে ধীরে প্রতীক ও বর্ণভিত্তিক লিপির সৃষ্টি হয়।
ভারতীয় উপমহাদেশে লিপির বিকাশ
ভারতীয় উপমহাদেশে প্রাচীনতম গুরুত্বপূর্ণ লিপিগুলোর মধ্যে ব্রাহ্মী লিপি অন্যতম।
এই ব্রাহ্মী লিপি থেকেই পরবর্তীকালে বিভিন্ন আঞ্চলিক লিপির জন্ম হয়।
বাংলা লিপির বিকাশ
ব্রাহ্মী লিপি থেকে ধীরে ধীরে—
গুপ্ত লিপি ➔ সিদ্ধমাত্রিকা লিপি ➔ গৌড়ীয় (গৌড়) লিপি বিকশিত হয়ে বর্তমান বাংলা লিপির সৃষ্টি হয়েছে।

৫. ব্রাহ্মী লিপি
পরিচয়: ব্রাহ্মী লিপি ভারতীয় উপমহাদেশের অন্যতম প্রাচীন ও গুরুত্বপূর্ণ লিপি।
বৈশিষ্ট্য:
- ভারতীয় বহু লিপির মূল উৎস।
- বাম থেকে ডানে লেখা হয়।
- ধ্বনিভিত্তিক লিখন-পদ্ধতি।
- সহজ ও সুসংগঠিত বর্ণরূপ ছিল।
গুরুত্ব: বাংলা, দেবনাগরী, গুজরাটি, ওড়িয়া, গুরুমুখীসহ বহু লিপির ভিত্তি।

৬. বর্তমান বাংলা লিপি
পরিচয়: বর্তমানে বাংলা ভাষা লেখার জন্য যে লিপি ব্যবহার করা হয়, সেটিই বর্তমান বাংলা লিপি।
বৈশিষ্ট্য:
১. বাম থেকে ডানে লেখা হয়।
২. স্বরবর্ণ ও ব্যঞ্জনবর্ণ রয়েছে।
৩. মাত্রা (শিরোরেখা) ব্যবহৃত হয় (বেশিরভাগ বাংলা বর্ণের উপরে অনুভূমিক রেখা)।
৪. কারচিহ্ন ব্যবহৃত হয় (া, ি, ী, ু, ূ, ে, ৈ, ো, ৌ)।
৫. যুক্তবর্ণ ব্যবহৃত হয় (ক্ষ, ত্র, জ্ঞ, শ্র, দ্ধ)।
৬. বিরামচিহ্ন ব্যবহৃত হয় (।, ,, ?, !, :, ;)।
৭. ডিজিটাল ব্যবহারের উপযোগী (কম্পিউটার, মোবাইল, ইন্টারনেট ও ইউনিকোড)।

৭. বাংলা লিপির বিবর্তন (চার্ট)
চিত্রলিপি ➔ ব্রাহ্মী লিপি ➔ গুপ্ত লিপি ➔ সিদ্ধমাত্রিকা লিপি ➔ গৌড়ীয় (গৌড়) লিপি ➔ বর্তমান বাংলা লিপি

৮. বাংলা লিপির ব্যবহার
বাংলা লিপি ব্যবহৃত হয়—বই লেখায়, সংবাদপত্রে, শিক্ষা প্রতিষ্ঠানে, সরকারি নথিতে, সাহিত্য রচনায়, কম্পিউটার ও মোবাইলে, সামাজিক যোগাযোগমাধ্যমে, গবেষণাকর্মে।

৯. উদাহরণ
- স্বরবর্ণ: অ, আ, ই
- ব্যঞ্জনবর্ণ: ক, গ, ত
- কারচিহ্ন: া, ি, ু
- যুক্তবর্ণ: ক্ষ, ত্র, জ্ঞ
- বিরামচিহ্ন: । , ? !

১০. বাংলা লিপির বৈশিষ্ট্যের সারসংক্ষেপ
- লিখনের দিক: বাম থেকে ডানে
- বর্ণ: ১১টি স্বরবর্ণ, ৩৯টি ব্যঞ্জনবর্ণ
- উৎস: ব্রাহ্মী লিপি

১১. অনুশীলনী
ক) শূন্যস্থান পূরণ করো:
১. ভাষার ধ্বনিকে লিখে প্রকাশ করার পদ্ধতিকে _________ বলে।
২. বাংলা লিপির মূল উৎস _________ লিপি।
৩. বাংলা বর্ণমালায় _________টি স্বরবর্ণ রয়েছে।
৪. বর্তমান বাংলা লিপি _________ থেকে ডানে লেখা হয়।
৫. দুই বা ততোধিক ব্যঞ্জনবর্ণের মিলিত রূপকে _________ বলে।

খ) সংক্ষিপ্ত প্রশ্ন:
১. লিপি কী?
২. বাংলা বর্ণমালা কী?
৩. ব্রাহ্মী লিপির দুটি বৈশিষ্ট্য লেখো।
৪. বর্তমান বাংলা লিপির চারটি বৈশিষ্ট্য লেখো।
৫. বাংলা লিপির বিবর্তনের ধাপগুলো লেখো।

গ) রচনামূলক প্রশ্ন:
১. বাংলা ভাষার লিপির ইতিহাস আলোচনা করো।
২. ব্রাহ্মী লিপি থেকে বর্তমান বাংলা লিপির বিকাশ ব্যাখ্যা করো।
৩. বাংলা বর্ণমালার গঠন ও বৈশিষ্ট্য উদাহরণসহ আলোচনা করো।
৪. বাংলা লিপির গুরুত্ব ও আধুনিক ব্যবহার বিশ্লেষণ করো।

অধ্যায়ের সারসংক্ষেপ:
- লিপি হলো ভাষার ধ্বনিকে বর্ণ বা চিহ্নের মাধ্যমে লিখে প্রকাশ করার পদ্ধতি।
- বাংলা বর্ণমালা ১১টি স্বরবর্ণ ও ৩৯টি ব্যঞ্জনবর্ণ নিয়ে গঠিত।
- বাংলা লিপির উৎপত্তি ব্রাহ্মী লিপি থেকে; পরবর্তীতে গুপ্ত, সিদ্ধমাত্রিকা ও গৌড়ীয় লিপির বিবর্তনের মাধ্যমে বর্তমান বাংলা লিপির সৃষ্টি হয়েছে।
