১. বাংলা সাহিত্যের সূচনা
পরিচয়
বাংলা সাহিত্য বলতে বাংলা ভাষায় রচিত সকল সাহিত্যকর্মকে বোঝায়। কবিতা, গল্প, উপন্যাস, নাটক, প্রবন্ধ, জীবনী, ভ্রমণকাহিনি, কাব্য ইত্যাদি বাংলা সাহিত্যের অন্তর্ভুক্ত।
বাংলা সাহিত্যের ইতিহাস প্রায় এক হাজার বছরেরও বেশি পুরোনো। এর সূচনা ঘটে চর্যাপদ রচনার মাধ্যমে। এরপর ধাপে ধাপে বাংলা সাহিত্য প্রাচীন যুগ, মধ্যযুগ এবং আধুনিক যুগে বিকশিত হয়েছে।

২. চর্যাপদ
পরিচয়: চর্যাপদ বাংলা সাহিত্যের প্রাচীনতম নিদর্শন এবং বাংলা ভাষার প্রথম সাহিত্যকর্ম হিসেবে স্বীকৃত। এটি মূলত বৌদ্ধ সহজিয়া সাধকদের রচিত ধর্মীয় ও আধ্যাত্মিক গানের সংকলন।
আবিষ্কার: ১৯০৭ সালে হরপ্রসাদ শাস্ত্রী নেপালের রাজদরবারের গ্রন্থাগার থেকে চর্যাপদের পুঁথি আবিষ্কার করেন।
রচনাকাল: প্রায় দশম থেকে দ্বাদশ শতাব্দী।
রচয়িতা: চর্যাপদের রচয়িতারা ছিলেন সিদ্ধাচার্য নামে পরিচিত বৌদ্ধ সাধক। উল্লেখযোগ্য—লুইপা, কাহ্নপা, ভুসুকুপা, শবরপা, কুক্কুরীপা, সরহপা, তান্তিপা।
বিষয়বস্তু: ধর্মীয় শিক্ষা, আধ্যাত্মিক সাধনা, মানবজীবনের দর্শন, রূপক ও প্রতীকের ব্যবহার।
গুরুত্ব: বাংলা সাহিত্যের সূচনা করে, ভাষার প্রাচীন রূপ সম্পর্কে ধারণা দেয়।

৩. প্রাচীন বাংলা সাহিত্য
সময়কাল: প্রায় ৯৫০–১২০০ খ্রিস্টাব্দ।
বৈশিষ্ট্য: ধর্মীয় প্রভাব প্রবল (বৌদ্ধ সহজিয়া মতবাদ), গীতিকবিতা প্রধান, রূপক ও প্রতীকধর্মী ভাষা।
প্রধান সাহিত্য: চর্যাপদ।

৪. মধ্যযুগের বাংলা সাহিত্য
সময়কাল: প্রায় ১২০১–১৮০০ খ্রিস্টাব্দ।
বৈশিষ্ট্য:
১. ধর্মীয় সাহিত্য (বৈষ্ণব, শাক্ত ও ইসলামি সাহিত্য)।
২. মঙ্গলকাব্য (মনসামঙ্গল, চণ্ডীমঙ্গল, ধর্মমঙ্গল)।
৩. বৈষ্ণব পদাবলি (রাধা-কৃষ্ণের প্রেমভক্তি)।
৪. অনুবাদ সাহিত্য (রামায়ণ, মহাভারত, ভাগবত)।
৫. মুসলিম সাহিত্য (আলাওল, শাহ মুহম্মদ সগীর, সৈয়দ সুলতান)।
উল্লেখযোগ্য কবি: বড়ু চণ্ডীদাস, কৃত্তিবাস ওঝা, কাশীরাম দাস, আলাওল, মুকুন্দরাম চক্রবর্তী, ভারতচন্দ্র রায়গুণাকর।

৫. আধুনিক যুগের বাংলা সাহিত্য
সময়কাল: প্রায় ১৮০১ খ্রিস্টাব্দ থেকে বর্তমান পর্যন্ত।
বৈশিষ্ট্য:
১. নতুন সাহিত্যধারা (উপন্যাস, ছোটগল্প, নাটক, প্রবন্ধ, আধুনিক কবিতা)।
২. সমাজ সংস্কার ও মানবতাবাদ।
৩. বাস্তবধর্মী সাহিত্য ও প্রমিত বাংলা।
উল্লেখযোগ্য সাহিত্যিক: ঈশ্বরচন্দ্র বিদ্যাসাগর, বঙ্কিমচন্দ্র চট্টোপাধ্যায়, মাইকেল মধুসূদন দত্ত, রবীন্দ্রনাথ ঠাকুর, কাজী নজরুল ইসলাম, শরৎচন্দ্র চট্টোপাধ্যায়, জসীমউদ্দীন, জীবনানন্দ দাশ, বিভূতিভূষণ বন্দ্যোপাধ্যায়, মানিক বন্দ্যোপাধ্যায়।

৬. বাংলা সাহিত্যের যুগভাগ (চার্ট)
প্রাচীন যুগ (৯৫০–১২০০) ➔ মধ্যযুগ (১২০১–১৮০০) ➔ আধুনিক যুগ (১৮০১–বর্তমান)

৭. তুলনামূলক সারণি
- প্রাচীন যুগ (৯৫০–১২০০): বৌদ্ধ ধর্মীয় সাহিত্য (চর্যাপদ)
- মধ্যযুগ (১২০১–১৮০০): মঙ্গলকাব্য, বৈষ্ণব পদাবলি, অনুবাদ সাহিত্য (মনসামঙ্গল, রামায়ণ)
- আধুনিক যুগ (১৮০১–বর্তমান): উপন্যাস, গল্প, নাটক, আধুনিক কবিতা (গীতাঞ্জলি, পথের পাঁচালী)

৮. গুরুত্বপূর্ণ তথ্য
- বাংলা সাহিত্যের প্রথম নিদর্শন চর্যাপদ।
- চর্যাপদ আবিষ্কার করেন হরপ্রসাদ শাস্ত্রী (১৯০৭)।
- মধ্যযুগে মঙ্গলকাব্য ও বৈষ্ণব পদাবলি বিশেষভাবে বিকশিত হয়।
- আধুনিক যুগে রবীন্দ্রনাথ ঠাকুর বাংলা সাহিত্যকে বিশ্বসাহিত্যে বিশেষ মর্যাদা এনে দেন।

৯. অনুশীলনী
ক) শূন্যস্থান পূরণ করো:
