২. চর্যাপদ আবিষ্কার করেন __________।
৩. বাংলা সাহিত্যের মধ্যযুগের সময়কাল __________ থেকে __________ খ্রিস্টাব্দ।
৪. বাংলা সাহিত্যের আধুনিক যুগ শুরু হয় প্রায় __________ খ্রিস্টাব্দ থেকে।
৫. মঙ্গলকাব্য বাংলা সাহিত্যের __________ যুগের অন্যতম প্রধান ধারা।

খ) সংক্ষিপ্ত প্রশ্ন:
১. চর্যাপদ কী?
২. চর্যাপদের বিষয়বস্তু কী ছিল?
৩. প্রাচীন বাংলা সাহিত্যের বৈশিষ্ট্য লেখো।
৪. মধ্যযুগের বাংলা সাহিত্যের তিনটি বৈশিষ্ট্য লেখো।
৫. আধুনিক বাংলা সাহিত্যের তিনজন সাহিত্যিকের নাম লেখো।

গ) রচনামূলক প্রশ্ন:
১. বাংলা সাহিত্যের সূচনা সম্পর্কে বিস্তারিত আলোচনা করো।
২. চর্যাপদের আবিষ্কার, বৈশিষ্ট্য ও গুরুত্ব ব্যাখ্যা করো।
৩. বাংলা সাহিত্যের প্রাচীন, মধ্য ও আধুনিক যুগের তুলনামূলক আলোচনা করো।
৪. আধুনিক বাংলা সাহিত্যের বিকাশে প্রধান সাহিত্যিকদের অবদান বিশ্লেষণ করো।

