২. রবীন্দ্রনাথ ঠাকুরের বাংলা সাহিত্য ও ভাষায় অবদান বিশ্লেষণ করো।
৩. কাজী নজরুল ইসলামের সাহিত্যকর্ম ও বাংলা ভাষায় অবদান ব্যাখ্যা করো।
৪. ড. মুহম্মদ শহীদুল্লাহ ও সুনীতিকুমার চট্টোপাধ্যায়ের ভাষাতাত্ত্বিক অবদান আলোচনা করো।

অধ্যায়ের সারসংক্ষেপ:
- বিদ্যাসাগর বাংলা গদ্য ও বর্ণমালা সংস্কার করেন।
- রবীন্দ্রনাথ ঠাকুর ১৯১৩ সালে নোবেল পুরস্কার পান।
- কাজী নজরুল ইসলাম বাংলাদেশের জাতীয় কবি।
- ড. মুহম্মদ শহীদুল্লাহ ও সুনীতিকুমার চট্টোপাধ্যায় বাংলা ভাষার বৈজ্ঞানিক গবেষণা ও ইতিহাস সুপ্রতিষ্ঠিত করেন।
