১. বাংলা ভাষা সম্পর্কে গুরুত্বপূর্ণ তথ্য
পরিচয়
বাংলা ভাষা বিশ্বের অন্যতম সমৃদ্ধ, মধুর ও বহুল ব্যবহৃত ভাষা। এটি বাংলাদেশ ও ভারতের একটি প্রধান ভাষা এবং বিশ্বের বিভিন্ন দেশে বসবাসরত বাঙালিদের মাধ্যমে ব্যবহৃত হয়।

২. বিশ্বের কত মানুষ বাংলা ভাষায় কথা বলে
- বর্তমানে পৃথিবীতে প্রায় ৩০ কোটির (৩০০ মিলিয়নেরও বেশি) মানুষ বাংলা ভাষায় কথা বলে।
- বাংলাদেশের অধিকাংশ মানুষের মাতৃভাষা বাংলা।
- ভারতের পশ্চিমবঙ্গ, ত্রিপুরা ও আসামের কিছু অঞ্চলের প্রধান ভাষা।

৩. বাংলা ভাষার অবস্থান
- বিশ্বের সবচেয়ে বেশি ব্যবহৃত ভাষাগুলোর মধ্যে প্রায় ৭ম স্থানে রয়েছে।
- ভাষা পরিবার: ইন্দো-ইউরোপীয় ➔ ইন্দো-আর্য ➔ মাগধী প্রাকৃত ➔ অপভ্রংশ ➔ বাংলা।

৪. বাংলা একাডেমি
- প্রতিষ্ঠা: ৩ ডিসেম্বর ১৯৫৫ সালে, ঢাকা।
- প্রধান কাজ: গবেষণা, অভিধান ও ব্যাকরণ প্রকাশ, একুশে বইমেলার আয়োজন।

৫. বাংলা ভাষার সরকারি ব্যবহার
- বাংলাদেশ: রাষ্ট্রভাষা ও সরকারি ভাষা।
- ভারত: পশ্চিমবঙ্গ ও ত্রিপুরার সরকারি ভাষা, আসামের বরাক উপত্যকায় সরকারি কাজ।

৬. বাংলা ভাষার আন্তর্জাতিক মর্যাদা
- ২১ ফেব্রুয়ারি আন্তর্জাতিক মাতৃভাষা দিবস।
- ১৯৯৯ সালে UNESCO এই দিবস ঘোষণা করে এবং ২০০০ সাল থেকে বিশ্বব্যাপী পালিত হচ্ছে।

৭. সাধারণ জ্ঞান
- বাংলা ভাষার প্রথম সাহিত্যকর্ম: চর্যাপদ।
- প্রথম ব্যাকরণ রচয়িতা: মানোয়েল দা আসসুম্পসাঁও (১৭৪৩)।
- প্রথম নোবেলজয়ী সাহিত্যিক: রবীন্দ্রনাথ ঠাকুর (১৯১৩)।
- জাতীয় কবি: কাজী নজরুল ইসলাম।

