পরিচয়
বাংলা ব্যাকরণের চারটি প্রধান আলোচ্য বিষয়ের মধ্যে 'ধ্বনি তত্ত্ব' বা 'বর্ণতত্ত্ব' অন্যতম। ধ্বনি এবং সেই ধ্বনির লিখিত রূপ 'বর্ণ' নিয়ে ব্যাকরণের যে অংশে আলোচনা করা হয়, তাকে বর্ণতত্ত্ব বলে।

২. বর্ণতত্ত্বের গুরুত্ব
- ভাষার ধ্বনি ও বর্ণসমূহের সঠিক ব্যবহার শেখায়।
- শুদ্ধ উচ্চারণ ও সঠিক বানান রীতি গঠনে সাহায্য করে।
- যুক্তবর্ণের সঠিক বিশ্লেষণ ও প্রয়োগ সহজ করে।
- শব্দের রূপ ও কাঠামোগত গঠন স্পষ্ট করে।

৩. বর্ণতত্ত্বের প্রধান আলোচ্য বিষয়সমূহ
১. ধ্বনি (Phoneme) ও বর্ণ (Grapheme / Letter)
২. স্বরবর্ণ ও ব্যঞ্জনবর্ণের শ্রেণীবিভাগ
৩. কারচিহ্ন ও ফলার ব্যবহার
