সহজ কথায়— ধ্বনির লিখিত বা দৃশ্যমান রূপই হলো বর্ণ।

২. ধ্বনি ও বর্ণের সম্পর্ক
- ধ্বনি হলো শ্রুতিগ্রাহ্য (কানে শোনার বিষয়)।
- বর্ণ হলো দৃষ্টিগ্রাহ্য (চোখে দেখার বিষয়)।
- ধ্বনি হলো ভাষার অমূর্ত রূপ, আর বর্ণ হলো ভাষার মূর্ত (দৃশ্যমান) রূপ।

৩. বর্ণের প্রকারভেদ
বাংলা ভাষায় বর্ণ মূলত দুই প্রকার:
১. স্বরবর্ণ (Vowels): স্বরধ্বনির লিখিত রূপ (১১টি)।
২. ব্যঞ্জনবর্ণ (Consonants): ব্যঞ্জনধ্বনির লিখিত রূপ (৩৯টি)।

