২. লিপির বিবর্তন ধারা
বাংলা লিপির উৎপত্তি প্রাচীন ভারতের 'ব্রাহ্মী লিপি'র পূর্বাঞ্চলীয় রূপ থেকে। এর বিবর্তনের ধাপগুলো হলো:
১. ব্রাহ্মী লিপি (প্রাচীনতম উৎস)
২. গুপ্ত লিপি (৪র্থ-৫ম শতাব্দী)
৩. সিদ্ধমাত্রিকা বা কুটিল লিপি (৬ষ্ঠ-৯ম শতাব্দী)
৪. গৌড়ীয় লিপি (১০ম-১২শ শতাব্দী)
৫. আধুনিক বাংলা লিপি (১৮ শতকে ছাপাখানা ও বিদ্যাসাগরের সংস্কারের মাধ্যমে প্রমিতকরণ)

৩. ছাপাখানা ও প্রমিতকরণ
- ১৭৭৮ সালে চার্লস উইলকিন্স ও পঞ্চানন কর্মকার বাংলায় প্রথম মেটাল টাইপ (ছাপা হরফ) তৈরি করেন।
- ঈশ্বরচন্দ্র বিদ্যাসাগর 'বর্ণপরিচয়' রচনার মাধ্যমে বাংলা বর্ণমালা সংস্কার ও সুসংগঠিত করেন।

