যেসব বর্ণ অন্য কোনো বর্ণের সাহায্য ছাড়া নিজে নিজে স্পষ্টভাবে উচ্চারিত হতে পারে, সেগুলোকে স্বরবর্ণ বলে।
বাংলা বর্ণমালায় মোট ১১টি স্বরবর্ণ রয়েছে: অ, আ, ই, ঈ, উ, ঊ, ঋ, এ, ঐ, ও, ঔ।

২. স্বরবর্ণের শ্রেণীবিভাগ
উচ্চারণের সময়কাল অনুযায়ী স্বরবর্ণ দুই প্রকার:
১. হ্রস্বস্বর (৪টি): অ, ই, উ, ঋ (উচ্চারণে কম সময় লাগে)।
২. দীর্ঘস্বর (৭টি): আ, ঈ, ঊ, এ, ঐ, ও, ঔ (উচ্চারণে বেশি সময় লাগে)।

৩. কারচিহ্ন (১০টি)
স্বরবর্ণ যখন ব্যঞ্জনবর্ণের সাথে যুক্ত হয়ে ব্যবহৃত হয়, তখন এর সংক্ষিপ্ত রূপ ব্যবহৃত হয়। স্বরবর্ণের এই সংক্ষিপ্ত রূপকে 'কার' বা 'কারচিহ্ন' বলে।
- 'অ' বর্ণের নিজস্ব কোনো কারচিহ্ন নেই (এজন্য একে 'নীলীন বর্ণ' বা বিলীন বর্ণ বলা হয়)।
- বাকি ১০টি স্বরবর্ণের কারচিহ্ন রয়েছে: া, ি, ী, ু, ূ, ে, ৈ, ো, ৌ।

