১. হ্রস্ব স্বর (অ, ই, উ, ঋ): উচ্চারণে কম সময় লাগে।
২. দীর্ঘ স্বর (আ, ঈ, ঊ, এ, ঐ, ও, ঔ): উচ্চারণে বেশি সময় লাগে।

২. উচ্চারণভেদে স্বরবর্ণ
ক) মুখ খোলার পরিমাণ অনুযায়ী:
- বিবৃত (খোলা): আ
- অর্ধ-বিবৃত: অ, ও
- সংবৃত (বন্ধ): ই, ঈ, উ, ঊ

খ) জিহ্বার অবস্থান অনুযায়ী:
- সম্মুখ স্বর: ই, ঈ, এ
- মধ্য স্বর: অ
- পশ্চাৎ স্বর: আ, উ, ঊ, ও, ঔ

গ) ঠোঁটের অবস্থান অনুযায়ী:
- গোলাকার (Rounded): উ, ঊ, ও, ঔ
- অগোলাকার (Unrounded): অ, আ, ই, ঈ, এ, ঐ, ঋ

৩. বাস্তব উচ্চারণ ও প্রমিত রীতি
আধুনিক প্রমিত চলিত বাংলায় ই–ঈ এবং উ–ঊ এর উচ্চারণে দৈর্ঘ্যগত স্পষ্ট পার্থক্য অনেক ক্ষেত্রে শোনা যায় না (যেমন: দিন/দীন, কুল/কূল), তবে ব্যাকরণিক শ্রেণিবিন্যাসে এই পার্থক্য বজায় রাখা হয়।

