এগুলো কণ্ঠ্য স্পর্শ বর্ণ, অর্থাৎ কণ্ঠের পশ্চাৎভাগে জিহ্বার সংস্পর্শে উচ্চারিত হয়।

২. ক-বর্গের বর্ণসমূহের উচ্চারণ বিবরণ
- ক: অঘোষ, অল্পপ্রাণ (উদা: কলম, কাক, কাগজ)
- খ: অঘোষ, মহাপ্রাণ (উদা: খবর, খাতা, খেলা)
- গ: ঘোষ, অল্পপ্রাণ (উদা: গরু, গান, গোলাপ)
- ঘ: ঘোষ, মহাপ্রাণ (উদা: ঘর, ঘণ্টা, ঘুড়ি)
- ঙ: ঘোষ, নাসিক্য (উদা: রঙ, অঙ্গ, গঙ্গা)

৩. বৈশিষ্ট্য
- মোট ৫টি বর্ণ।
- কণ্ঠ থেকে উচ্চারিত হয়।
- স্পর্শ বর্ণের প্রথম বর্গ।

