২. যুক্তবর্ণ গঠনের প্রক্রিয়া
ব্যঞ্জন + হসন্ত (্) + ব্যঞ্জন = যুক্তবর্ণ।
উদাহরণ:
- ক + ্ + ত = ক্ত (শক্তি, ব্যক্তি)
- ক + ্ + ষ = ক্ষ (শিক্ষা, রক্ষা)
- জ + ্ + ঞ = জ্ঞ (জ্ঞান, বিজ্ঞান)
- শ + ্ + র = শ্র (শ্রদ্ধা, শ্রী)
- ন + ্ + দ = ন্দ (আনন্দ, সুন্দর)

৩. তিন বর্ণের যুক্তবর্ণ
- স + ত + র = স্ত্র (স্ত্রী, শাস্ত্র)
- ন + দ + র = ন্দ্র (ইন্দ্র)

