১. পূর্ণাঙ্গ মডেল টেস্ট কাঠামো
- বহুনির্বাচনী প্রশ্ন (MCQ): বর্ণমালা, উচ্চারণস্থান, উচ্চারণরীতি, কারচিহ্ন, ফলা, যুক্তবর্ণ, বর্ণ বিশ্লেষণ ও বর্ণ গণনা।
- লিখিত প্রশ্ন: বর্ণ ও ধ্বনির পার্থক্য, স্পর্শ ও উষ্ম বর্ণ, অযোগবাহ বর্ণের ব্যবহার, প্রমিত বানান ও বর্ণ পরিবর্তনের নিয়ম।

২. দ্রুত রিভিশন টিপস
- বর্ণ = ৫০টি (১১টি স্বরবর্ণ + ৩৯টি ব্যঞ্জনবর্ণ)।
- কারচিহ্ন = ১০টি (অ-এর কারচিহ্ন নেই)।
- অযোগবাহ = ৩টি (ং, ঃ, ঁ)।
- ক্ষ = ক+ষ, জ্ঞ = জ+ঞ, ত্র = ত+র, শ্র = শ+র।
- কারচিহ্নকে বর্ণ গণনায় নেওয়া যাবে না।

৩. চূড়ান্ত প্রস্তুতি টিপস
পরীক্ষার পূর্বে অধ্যায় ৫৮ ও ৬০-এর দ্রুত রিভিশন নোটসমূহ বারবার চোখ বুলিয়ে নিন।
